#include <cstddef>
#include <vector>
#include <iostream>

int main() {
    std::vector<int> v(10);

    // size_t for size/index
    size_t s = v.size(); 

    // ptrdiff_t for difference
    std::ptrdiff_t diff = v.end() - v.begin();

    // Subtraction pitfall:
    size_t a = 5, b = 10;
    size_t c = a - b; // c is a huge positive number (unsigned wrap-around)

    std::cout << "Size: " << s << " (size_t)\n";
    std::cout << "Diff: " << diff << " (ptrdiff_t)\n";

    // Correct difference calculation:
    std::ptrdiff_t safe_diff = (std::ptrdiff_t)a - (std::ptrdiff_t)b; 
    std::cout << "Safe Diff: " << safe_diff << "\n";
}
